// client/src/features/dashboard/attendee/JoinSession.jsx
import React, { useEffect, useRef } from 'react';
import { useLocation, Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const JoinSession = () => {
  const containerRef = useRef(null);
  const { search } = useLocation();
  // our "room name" is whatever you passed in the ?link=… param
  const roomName = new URLSearchParams(search).get('link');

  useEffect(() => {
    if (!roomName || !window.JitsiMeetExternalAPI) return;

    const domain = 'meet.jit.si';
    const options = {
      roomName,
      parentNode: containerRef.current,
      width: '100%',
      height: 600,
      interfaceConfigOverwrite: {},
      configOverwrite: {}
    };
    const api = new window.JitsiMeetExternalAPI(domain, options);

    return () => {
      // always try dispose() and swallow any error
      try {
        api.dispose();
      } catch (e) {
        // ignore
      }
    };
  }, [roomName]);

  return (
    <div className="container">
      <div className="card">
        <h2>Live Session</h2>

        {roomName ? (
          <div
            ref={containerRef}
            style={{ width: '100%', height: '600px' }}
          />
        ) : (
          <p style={{ color: 'red' }}>No session link provided.</p>
        )}

        <Link to="/attendee/dashboard">
          <button className="btn" style={{ marginTop: '1rem' }}>
            Back to Dashboard
          </button>
        </Link>
      </div>
    </div>
  );
};

export default JoinSession;
